"""Read-only per-account known settlement reconciliation and next-window handoff."""
import collections,gzip,json
from decimal import Decimal as D
from common import ROOT,R,sha,rel,put,now
rd=lambda p:json.loads(p.read_text())
def main():
 source=R/'funding16_nov19_preflight.json';pre=rd(R/'actual16_nov19_prebinding_source.json');src=rd(source);aw=rd(R/'account_window_verification.json');w=rd(R/'account_windows.json');ns=rd(R/'next_research_state.json');h=ns['UTC_midnight_handoff'];expected=collections.Counter();lookup={}
 assert pre['passed'] and pre['before_any_current_reservation'] and sha(source)==pre['sha256'] and src['recorded_utc']==pre['first_capture_utc']
 for asset,rows in src['public_fields_by_asset'].items():
  for z in rows:
   timestamp=int(z['fundingTime'])*1000000;expected[str(timestamp)]+=3;lookup[asset,timestamp]=z
 assert expected and aw['passed']
 previous_h=rd(ROOT/'research/experiments/20261120T063909Z/next_research_state.json')['UTC_midnight_handoff'];first_path=previous_h['original_Nov19_16_authoritative_source_path'];assert sha(ROOT/first_path)==sha(source) and previous_h['original_Nov19_16_capture_utc']==src['recorded_utc']
 flows=[];books={}
 for stem in ['candidate','l4h02','fewm']:
  folder=R/(stem+'_observation');before=rd(ROOT/rd(folder/'previous_pointer.json')['state']);after=rd(folder/'state.json');delta=json.loads(gzip.decompress((folder/'delta.json.gz').read_bytes()));journal=[z for z in delta['journal'] if z['kind']=='funding'];assert len(journal)==w[stem]['expected_funding_records'];seen=set()
  for z in journal:
   key=z['asset'],z['timestamp_ns'];assert key in lookup;row=lookup[key];k=str(z['cost_multiplier']);unique=(z['asset'],k,z['timestamp_ns']);assert unique not in seen;seen.add(unique);q=D(z['signed_units']);assert q==D(before['books'][z['asset']][k]['signed_units']);base=-q*D(row['markPrice'])*D(row['fundingRate']);amount=base*int(k) if base<0 else base;assert D(z['base_amount_usdt'])==base and D(z['amount_usdt'])==amount
   flows.append({'account':stem,'asset':z['asset'],'cost':k,'actual_settlement_ns':z['timestamp_ns'],'own_held_units':str(q),'own_amount_usdt':str(amount),'cash_before':z['cash_before'],'cash_after':z['cash_after'],'original_first_capture_utc':src['recorded_utc']})
  for timestamp,count in expected.items():assert aw['full_chain_once_counts'][stem]['funding'][timestamp]==count
  books[stem]={'state_sha256':sha(folder/'state.json'),'actual_current_new_journal_funding_rows':len(journal),'asset_cost_timestamp_keys_unique':True,'known_event_full_chain_booked_exactly_once':True}
 candidate_counts={timestamp:aw['full_chain_once_counts']['candidate']['funding'][timestamp] for timestamp in expected};pending={timestamp:expected[timestamp]-count for timestamp,count in candidate_counts.items()};assert not any(pending.values()) and aw['current_funding_records_by_account']=={'SMA':0,'candidate':6,'l4h02':0,'fewm':0}
 h.update(actual_Nov19_16_source=rel(source),actual_Nov19_16_source_sha256=sha(source),original_Nov19_16_authoritative_source_path=first_path,original_Nov19_16_capture_utc=src['recorded_utc'],known_actual_Nov19_16_public_fields=src['public_fields_by_asset'],actual_Nov19_16_settlement_ns=sorted(expected),L4_FEWM_actualNov19_16_booked_once=True,single_actualNov19_16_not_yet_booked=False,all3_perp_actualNov19_16_booked_once=True,candidate_actualNov19_16_current_once_counts=candidate_counts,candidate_actualNov19_16_pending_counts=pending)
 assert h['next_SMA_single_window_utc']==['2026-11-19T16:30:00Z','2026-11-19T18:30:00Z'] and h['next_L4_FEWM_window_utc']==['2026-11-19T18:10:00Z','2026-11-19T20:10:00Z']
 action={'all3_original_perps_known_Nov19_16_booked_once':True,'actual_known_pending_event_ns':[],'first_source':rel(source),'first_source_sha256':sha(source),'original_first_source_UTC':src['recorded_utc'],'reuse_exact_original_fields_not_nominal_time':True,'fresh_full_window_actual_query_before_any_next_reserve':True,'do_not_repeat_Nov19_00_08_16_or_copy_other_accounts_cashflows':True,'cash_and_quantity_not_reset_or_forced_closed':True,'do_not_prebook_future_events':True};h['next_SMA_single_preparation_action']['candidate_actualNov19_16_preparation']=action;h['next_L4_FEWM_preparation_action'].update(action);h['next_nominal_boundary_handoff']=action;h['next_window_funding_action']='All3originalperps have now booked the exact knownNov19_16:00:00.002 event once. Currentcandidate used its own inherited q/costs,not L4/FEWM cashflows;L4/FEWM currentwindow did not repeat. NextSMA/candidate16:30-18:30 andL4/FEWM18:10-20:10 must freshquery actual events,neverassume nominal funding schedule,neverrepeat known events. Preserve original firstNov19_16 source UTC/bytes.';h['rules'] += ' 本轮candidate按自己的原持仓/成本记入已知Nov19 16:00:00.002结算，L4/FEWM未重复。三永续均已恰好记该事件一次；首次来源UTC='+src['recorded_utc']+'和SHA保持，下一窗口只处理实际新增事件。'
 put(R/'funding16_nov19_reconciliation.json',{'passed':True,'recorded_utc':now(),'source':rel(source),'source_sha256':sha(source),'original_authoritative_source_path':first_path,'original_first_capture_utc':src['recorded_utc'],'actual_fields':src['public_fields_by_asset'],'pre_reservation_binding':pre,'expected_once_counts_per_account':dict(expected),'current_funding_records_by_account':aw['current_funding_records_by_account'],'actual_own_cashflows':flows,'current_own_books':books,'candidate_current_once_counts':candidate_counts,'candidate_pending_counts_next_window':pending,'all3_perps_now_booked_once':True,'source_first_time_never_relabeled':True,'no_financial_or_account_reexecution':True});ns['UTC_midnight_handoff']=h;put(R/'next_research_state.json',ns)
 with (R/'result.md').open('a') as f:f.write('\n原账户实际资金费新增分配='+json.dumps(aw['current_funding_records_by_account'],ensure_ascii=False)+'。candidate使用自身BTC-0.012/ETH0原持仓及原成本规则，逐笔现金流见funding16_nov19_reconciliation.json；L4/FEWM不重复既有16结算。三永续现均恰好记Nov19实际16:00:00.002一次；首完整来源UTC='+src['recorded_utc']+'、SHA256='+sha(source)+'原样保留。下一SMA/candidate16:30→18:30，L4/FEWM18:10→20:10，均先完整查询实际新增结算，不按名义时间预记、不重置本金/持仓，下一日决策Nov20 00:01。\n')
 print(json.dumps({'known_actual_Nov19_16_all3_booked_once':True,'current_funding_split':aw['current_funding_records_by_account'],'candidate_pending':pending,'original_first_capture_utc':src['recorded_utc'],'no_reexecution':True}),flush=True)
